// План specs/pricebook.md 1.2 (кейс .qa/tests/pricebook/PB-02). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: Job Details автосохраняет — в первую работу добавляется позиция «QA-AUTO pb-job-line …», в конце удаляется из Items.
import { test, expect } from '../../fixtures';
import {
  ROLE, addManualItem, expectNotInPriceBook, itemRow, openFirstJobItems, openPriceBook, priceBookTotal, removeItemRow, stamp, watchPriceBookWrites,
} from './pricebook-helpers';

test.describe('Price Book — только ручные позиции (#df9bec)', () => {
  test('QA-AUTO: item typed in Job → Items → Add Item stays only in the job, not added to Price Book #df9bec @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(ROLE);
    const item = { name: `QA-AUTO pb-job-line ${stamp()}`, price: '1' };
    let jobUrl: string | null = null;
    try {
      // Шаг 1: Total Items до
      await openPriceBook(page);
      const before = await priceBookTotal(page);

      // Шаги 2–3: первая работа → Items → Add Item
      const writes = watchPriceBookWrites(page);
      await openFirstJobItems(page);
      jobUrl = page.url();
      await addManualItem(page, item);
      await expect(itemRow(page, item.name)).toHaveCount(1);
      // после перезагрузки позиция в работе осталась (сохранена в документе)
      await page.reload();
      await expect(itemRow(page, item.name)).toHaveCount(1);
      expect(writes, 'POST/PATCH/PUT к PriceBook при добавлении позиции в работу').toEqual([]);

      // Шаг 4: Price Book — число позиций то же, поиск пуст (источник: «מה רצוי» — או עבודה/חשבונית)
      await expectNotInPriceBook(page, item.name, before);
      expect(writes, 'запросов записи в PriceBook нет').toEqual([]);
    } finally {
      if (jobUrl && !page.isClosed()) {
        await page.goto(jobUrl).catch(() => {});
        await removeItemRow(page, item.name);
      }
    }
  });
});
